content:
@layer components {
  .book-card {
    border-radius: var(--shelf-radius-md);
    background-color: var(--shelf-bgColor-raised);
    box-shadow: var(--shelf-shadow-md);
    transition: background-color 200ms;
  }
}

@layer components {
  .drawer {
    position: fixed;
    inset-block: 0;
    inline-size: min(24rem, 90vw);
    background-color: var(--shelf-bgColor-raised);
    transition: transform 200ms;
  }
}

@layer components {
  .book-card {
    border-radius: var(--shelf-radius-md);
    background-color: var(--shelf-bgColor-raised);
    transition: opacity 200ms;
  }
}

@layer components {
  @keyframes expand {
    from {
      width: 0;
      opacity: 0;
    }
    to {
      width: 100%;
      opacity: 1;
    }
  }

  .shelf-grid {
    display: grid;
    gap: var(--shelf-space-md);
  }
}

@layer components {
  @keyframes slide-in {
    from {
      transform: translateX(100%);
      opacity: 0;
    }
    to {
      transform: translateX(0);
      opacity: 1;
    }
  }

  .drawer {
    position: fixed;
    animation-name: slide-in;
  }
}

@layer components {
  .chip {
    display: inline-flex;
    align-items: center;
    padding: var(--shelf-space-xs) var(--shelf-space-sm);
    border-radius: var(--shelf-radius-full);
    transition: color 0.3s;
  }
}

@layer tokens {
  :root {
    --shelf-motion-duration-fast: 150ms;
    --shelf-motion-duration-base: 300ms;
    --shelf-motion-easing-enter: cubic-bezier(0.0, 0.0, 0.2, 1);
    transition: background-color 200ms;
  }
}

@layer base {
  *, *::before, *::after { box-sizing: border-box; }
  body {
    margin: 0;
    background-color: var(--shelf-bgColor-default);
    color: var(--shelf-fgColor-default);
    font-family: var(--shelf-font-family-base);
  }
}

@layer components {
  .book-card {
    border-radius: var(--shelf-radius-md);
    background-color: var(--shelf-bgColor-raised);
    box-shadow: var(--shelf-shadow-md);
    transition: box-shadow 0.2s;
  }
}
